using System;
using System.Collections.Generic;

public static class Brackets
{
    /// <summary>
    /// Checks if the parentheses (), square brackets [], and curly braces {} in string s are balanced and properly nested.
    /// </summary>
    /// <param name="s">The input string to check.</param>
    /// <returns>
    /// -1 if the string is balanced; 
    /// The index of the first mismatched closing bracket or the index of the earliest unclosed opening bracket.
    /// </returns>
    public static int FirstError(string s)
    {
        if (s == null) return -1;

        // We use a List to act as our stack so that we can easily access 
        // the first element added (the earliest unclosed opener) if needed.
        var stack = new List<(char Character, int Index)>();

        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];

            // If character is an opening bracket, push it onto the stack with its index.
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Add((c, i));
            }
            // If character is a closing bracket...
            else if (c == ')' || c == ']' || c == '}')
            {
                // 1. Error: No corresponding opening bracket exists in the stack.
                if (stack.Count == 0)
                {
                    return i;
                }

                // Pop the last unclosed opener from the stack to check for a match.
                var top = stack[stack.Count - 1];
                stack.RemoveAt(stack.Count - 1);

                bool isMatch = (c == ')' && top.Character == '(') ||
                               (c == ']' && top.Character == '[') ||
                               (c == '}' && top.Character == '{');

                // 2. Error: The closing bracket does not match the most recent unclosed opener.
                if (!isMatch)
                {
                    return i;
                }
            }
        }

        // If we finished iterating and there are still items in the stack, it means
        // some openers were never closed. Return the index of the earliest one (the bottom of the stack).
        if (stack.Count > 0)
        {
            return stack[0].Index;
        }

        // Everything was matched and nested correctly.
        return -1;
    }
}

