public static class Brackets
{
    /// <summary>
    /// Checks if brackets (), [], and {} are balanced and properly nested.
    /// </summary>
    /// <param name="s">The string to validate.</param>
    /// <returns>
    /// -1 if the string is balanced; 
    /// the index of the first unmatched closing bracket if found;
    /// or the index of the earliest unclosed opening bracket.
    /// </returns>
    public static int FirstError(string s)
    {
        if (s == null) return -1;

        // Stack stores a tuple containing the character and its original index in the string
        Stack<(char Char, int Index)> stack = new Stack<(char Char, int Index)>();

        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];

            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push((c, i));
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    // Found a closing bracket with no corresponding opener
                    return i;
                }

                var top = stack.Peek();
                bool matches = false;

                if (c == ')' && top.Char == '(') matches = true;
                else if (c == ']' && top.Char == '[') matches = true;
                else if (c == '}' && top.Char == '{') matches = true;

                if (!matches)
                {
                    // Closing bracket does not match the most recent unclosed opener
                    return i;
                }

                stack.Pop();
            }
        }

        if (stack.Count > 0)
        {
            // There are leftover openers. 
            // To find the "earliest" unclosed opener, we must inspect the stack contents.
            // Since a Stack is LIFO, the earliest one pushed is at the bottom.
            // We convert to an array/list or use a technique to get the first-pushed element.
            int earliestIndex = int.MaxValue;
            foreach (var item in stack)
            {
                if (item.Index < earliestIndex)
                {
                    earliestIndex = item.Index;
                }
            }
            return earliestIndex;
        }

        return -1;
    }
}

