        // Store the bracket character and its original index in the string.
        Stack<(char Bracket, int Index)> stack = new Stack<(char Bracket, int Index)>();

        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];

            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push((c, i));
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                // If there is no opener for this closer, it's the first error.
                if (stack.Count == 0)
                {
                    return i;
                }

                var top = stack.Pop();

                // Check if the closing bracket matches the most recent opening bracket.
                if (!IsMatchingPair(top.Bracket, c))
                {
                    return i;
                }
            }
        }

        // If openers are left over, return the index of the earliest (bottom-most) opener.
        if (stack.Count > 0)
        {
            var remaining = stack.ToArray();
            // Stack.ToArray() returns elements in LIFO order, so the last element is the first pushed.
            return remaining[remaining.Length - 1].Index;
        }

        return -1;
    }

    private static bool IsMatchingPair(char open, char close)
    {
        return (open == '(' && close == ')') ||
               (open == '[' && close == ']') ||
               (open == '{' && close == '}');
