public static class Brackets
{
    public static int FirstError(string s)
    {
        char[] openers = new char[s.Length];
        int[] opIndices = new int[s.Length];
        int top = -1; 

        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '(' || c == '[' || c == '{')
            {
                openers[++top] = c;
                opIndices[top] = i;
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (top == -1) return i;

                char expectedClose;
                if (openers[top] == '(') expectedClose = ')';
                else if (openers[top] == '[') expectedClose = ']';
                else expectedClose = '}';

                if (c != expectedClose) return i;

                top--;
            }
        }

        return top >= 0 ? opIndices[0] : -1;
    }
}

