{
    public static int FirstError(string s)
    {
        var stack = new Stack<int>();

        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];

            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(i);
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                // Determine expected opening bracket and its char
                char expectedOpener;
                switch (c)
                {
                    case ')': expectedOpener = '('; break;
                    case ']': expectedOpener = '['; break;
                    case '}': expectedOpener = '{'; break;
                    default: continue; // Shouldn't happen for given closer set, but just in case
                }

                if (stack.Count == 0)
                {
                    return i;
                }

                int topIndex = stack.Peek();
                char topChar = s[topIndex];

                if (topChar != expectedOpener)
                {
                    return i;
                }

                stack.Pop();
            }
        }

        // If there are still unclosed openers, return the earliest one (which is at the bottom of the stack)
        if (stack.Count > 0)
        {
            // The earliest unclosed opener is the first one pushed, which is at the bottom.
            // Since Stack<T> pops from the top, we need to get the last element in push order.
            int[] indices = stack.ToArray();
            return indices[indices.Length - 1];
        }

        return -1;
    }
