public static class Geometry
{
    /// <summary>
    /// Returns the point on the line segment from a to b that is closest to p.
    /// If a and b are the same point, returns a.
    /// </summary>
    /// <param name="a">The start of the line segment.</param>
    /// <param name="b">The end of the line segment.</param>
    /// <param name="p">The point to find the closest point on the segment for.</param>
    /// <returns>The coordinates (X, Y) of the closest point on the segment.</returns>
    public static (double X, double Y) ClosestPointOnSegment((double X, double Y) a, (double X, double Y) b, (double X, double Y) p)
    {
        double dx = b.X - a.X;
        double dy = b.Y - a.Y;

        // Calculate the squared length of the segment ab
        double lengthSquared = dx * dx + dy * dy;

        // If a and b are the same point, lengthSquared will be 0
        if (lengthSquared == 0)
        {
            return a;
        }

        // Project vector ap onto vector ab to find the parameterized position t of the projection.
        // The formula for t is: dot(p - a, b - a) / |b - a|^2
        double t = ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / lengthSquared;

        if (t < 0)
        {
            // The closest point is the start of the segment
            return a;
        }
        else if (t > 1)
        {
            // The closest point is the end of the segment
            return b;
        }

        // The closest point lies on the segment between a and b
        return (a.X + t * dx, a.Y + t * dy);
    }
}

