    /// </summary>
    /// <param name="a">The starting point of the segment.</param>
    /// <param name="b">The ending point of the segment.</param>
    /// <param name="p">The target point.</param>
    /// <returns>A tuple representing the (X, Y) coordinates of the closest point on the segment.</returns>
    public static (double X, double Y) ClosestPointOnSegment((double X, double Y) a, (double X, double Y) b, (double X, double Y) p)
    {
        double dx = b.X - a.X;
        double dy = b.Y - a.Y;

        // Calculate the squared length of the segment ab
        double lengthSquared = dx * dx + dy * dy;

        // If a and b are the same point, return a
        if (lengthSquared == 0)
        {
            return a;
        }

        // Consider the line extending through a and b.
        // We find the projection of point p onto this line.
        // The parameter t is the normalized distance from a to the projection on the line.
        // t = [(p - a) . (b - a)] / |b - a|^2
        double t = ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / lengthSquared;

        // Clamp t to the range [0, 1] to stay on the line segment
        if (t < 0.0)
        {
            return a;
        }
        if (t > 1.0)
        {
            return b;
        }

        // Return the projected point
        return (a.X + t * dx, a.Y + t * dy);
    }
}

