public static class Geometry
{
    public static (double X, double Y) ClosestPointOnSegment((double X, double Y) a, (double X, double Y) b, (double X, double Y) p)
    {
        double abX = b.X - a.X;
        double abY = b.Y - a.Y;

        // Check if segment is degenerate (a and b are essentially the same point)
        if (Math.Abs(abX) < 1e-10 && Math.Abs(abY) < 1e-10)
            return a;

        double apX = p.X - a.X;
        double apY = p.Y - a.Y;

        // Calculate dot products for projection parameter
        double abDotAb = abX * abX + abY * abY;
        double apDotAb = apX * abX + apY * abY;

        // Clamp t to [0, 1] to ensure point stays on segment
        double t;
        if (abDotAb < 1e-20)
            t = 0;
        else
            t = Math.Max(0.0, Math.Min(1.0, apDotAb / abDotAb));

        return (a.X + t * abX, a.Y + t * abY);
    }
}

