public static class Geometry
{
    public static (double X, double Y) ClosestPointOnSegment((double X, double Y) a, (double X, double Y) b, (double X, double Y) p)
    {
        double dx = b.X - a.X;
        double dy = b.Y - a.Y;

        // If a and b are the same point, return a
        if (dx == 0.0 && dy == 0.0)
        {
            return a;
        }

        // Compute the projection parameter t of point p onto line segment ab
        double lengthSq = dx * dx + dy * dy;
        double t = ((p.X - a.X) * dx + (p.Y - a.Y) * dy) / lengthSq;

        // Clamp t to [0, 1] to stay on the segment
        if (t < 0.0) t = 0.0;
        else if (t > 1.0) t = 1.0;

        double closestX = a.X + t * dx;
        double closestY = a.Y + t * dy;

        return (closestX, closestY);
    }
}

public static class Geometry
{
    public static (double X, double Y) ClosestPointOnSegment((double X, double Y) a, (double X, double Y) b, (double X, double Y) p)
    {
        // Calculate the vector ab
        double dx = b.X - a.X;
        double dy = b.Y - a.Y;

        // Length squared of ab
        double lengthSquared = dx * dx + dy * dy;

        if (lengthSquared == 0)
        {
            return (a.X, a.Y);
        }

        // Calculate the parameter t for the projection of p onto the line through a and b
        // t = dot(p - a, b - a) / |b - a|^2
        double tx = p.X - a.X;
        double ty = p.Y - a.Y;

        double dot = tx * dx + ty * dy;
        double t = dot / lengthSquared;

        // Clamp t to [0, 1]
        if (t < 0)
            t = 0;
        else if (t > 1)
            t = 1;

        return (a.X + t * dx, a.Y + t * dy);
    }
}

