public class Cooldown
{
    private readonly int _durationTicks;
    private readonly int _maxCharges;
    private int _currentCharges;
    private int _timerTicks;

    public int Charges => _currentCharges;

    public Cooldown(int durationTicks, int maxCharges)
    {
        _durationTicks = durationTicks;
        _maxCharges = maxCharges;
        _currentCharges = maxCharges;
        _timerTicks = 0;
    }

    public bool TryUse()
    {
        if (_currentCharges > 0)
        {
            _currentCharges--;
            return true;
        }
        return false;
    }

    public void Tick()
    {
        if (_currentCharges < _maxCharges)
        {
            _timerTicks++;

            // If the timer reaches the required duration, restore a charge.
            if (_timerTicks >= _durationTicks)
            {
                _currentCharges++;
                // Recharging restarts from zero after a charge is restored when still below max.
                _timerTicks = 0;
            }
        }
        else
        {
            // The timer does not run while charges are full.
            _timerTicks = 0;
        }
    }
}

