public class Cooldown
{
    private readonly int _durationTicks;
    private readonly int _maxCharges;
    private int _charges;
    private int _rechargeTimer;
    private bool _isRecharging;

    public Cooldown(int durationTicks, int maxCharges)
    {
        if (durationTicks <= 0)
            throw new ArgumentOutOfRangeException(nameof(durationTicks), "Duration must be positive.");
        if (maxCharges <= 0)
            throw new ArgumentOutOfRangeException(nameof(maxCharges), "Max charges must be positive.");

        _durationTicks = durationTicks;
        _maxCharges = maxCharges;
        _charges = maxCharges;
        _rechargeTimer = 0;
        _isRecharging = false;
    }

    public int Charges
    {
        get => _charges;
    }

    public bool TryUse()
    {
        if (_charges > 0)
        {
            _charges--;
            return true;
        }
        return false;
    }

    public void Tick()
    {
        // If charges are full, don't recharge and stop any active recharge timer logic for charging purposes
        if (_charges >= _maxCharges)
        {
            _isRecharging = false;
            _rechargeTimer = 0;
            return;
        }

        // Start recharging if we have charges below max and not already recharging
        if (!_isRecharging)
        {
            _isRecharging = true;
            _rechargeTimer = 0;
        }

        _rechargeTimer++;

        if (_rechargeTimer >= _durationTicks && _charges < _maxCharges)
        {
            _charges++;
            _rechargeTimer = 0;

            // If we've reached max charges after this restore, stop recharging
            if (_charges >= _maxCharges)
            {
                _isRecharging = false;
                _rechargeTimer = 0;
            }
        }
    }
}

