public class Cooldown
{
    private readonly int _durationTicks;
    private readonly int _maxCharges;
    public int Charges { get; private set; }

    // Tracks how many ticks have passed since the last charge was restored (or since start)
    private int _rechargeTimer;

    public Cooldown(int durationTicks, int maxCharges)
    {
        if (durationTicks <= 0) throw new System.ArgumentOutOfRangeException(nameof(durationTicks), "Duration must be positive.");
        if (maxCharges <= 0) throw new System.ArgumentOutOfRangeException(nameof(maxCharges), "Max charges must be positive.");

        _durationTicks = durationTicks;
        _maxCharges = maxCharges;
        Charges = maxCharges;
        _rechargeTimer = 0;
    }

    public bool TryUse()
    {
        if (Charges < _maxCharges)
        {
            // Can use only if we have charges. Initially full, so can use immediately.
            // But wait: "It starts with maxCharges charges." and "Recharging restarts from zero after a charge is restored when still below max"
            // "Spending a charge while the timer is already running does not reset it."
            // If we are at max charges, we can use one. The timer doesn't run while full.

            if (Charges > 0)
            {
                Charges--;

                // If we just went from full to full-1, do we start the timer?
                // "the timer does not run while charges are full" implies that once it's not full, the timer should track progress.
                // However, usually cooldowns with charges recharge over time after being used.
                // Let's look at: "While Charges is below maxCharges, a recharge timer runs... Recharging restarts from zero after a charge is restored"

                // Case 1: Started full (max). Use one. Now at max-1. Timer should start counting towards the first recharge?
                // Or does the timer only count *after* you lose charges? Usually yes.
                // But here, if I start with 2/2, use 1 -> 1/2. The next charge takes `durationTicks` ticks. So timer starts at 0.

                // Case 2: We are below max, and timer is running (rechargeTimer > 0). Spending does NOT reset it. Correct.

                // Case 3: We are full, use one -> not full. Should we start the timer? Yes.

                if (Charges == _maxCharges - 1 && _rechargeTimer == 0)
                {
                    _rechargeTimer = 0; // Start counting from now.
                }

                return true;
            }
        }

        return false;
    }

    public void Tick()
    {
        if (Charges < _maxCharges)
        {
            _rechargeTimer++;

            if (_rechargeTimer >= _durationTicks)
            {
                Charges = Math.Min(Charges + 1, _maxCharges);

                // If we restored a charge and are still below max (or just hit max), restart the timer.
                // "Recharging restarts from zero after a charge is restored when still below max"
                // Wait, if I restore to full, do I stop? Yes, "timer does not run while charges are full".
                // If I'm still below max, I need another tick of durationTicks.

                _rechargeTimer = 0;
            }
        }
    }
}

public class Cooldown
{
    private readonly int _durationTicks;
    private readonly int _maxCharges;
    private int _charges;
    private int _ticksSinceLastRestore;
    private bool _timerRunning;

    public int Charges => _charges;

    public Cooldown(int durationTicks, int maxCharges)
    {
        if (durationTicks <= 0 || maxCharges < 1)
            throw new ArgumentException();
        _durationTicks = durationTicks;
        _maxCharges = maxCharges;
        _charges = maxCharges;
        _ticksSinceLastRestore = 0;
        _timerRunning = false; // no timer when full
    }

    public bool TryUse()
    {
        if (_charges > 0)
        {
            _charges--;
            // If charges were full, start the timer
            if (!_timerRunning && _charges < _maxCharges)
            {
                _timerRunning = true;
                _ticksSinceLastRestore = 0;
            }
            return true;
        }
        return false;
    }

    public void Tick()
    {
        if (!_timerRunning || _charges >= _maxCharges)
            return;

        _ticksSinceLastRestore++;
        if (_ticksSinceLastRestore >= _durationTicks)
        {
            // Restore one charge
            _charges++;
            _ticksSinceLastRestore = 0;

            if (_charges >= _maxCharges)
            {
                _timerRunning = false;
            }
        }
    }
}

using System;
using System.Collections.Generic;

public static class Routes
{
    /// <summary>
    /// Finds the shortest path between two nodes in a weighted directed graph using Dijkstra's algorithm.
    /// </summary>
    /// <param name="edges">An adjacency list representing the graph where edges[a][b] is the cost from a to b.</param>
    /// <param name="from">The starting node.</param>
    /// <param name="to">The target node.</param>
    /// <returns>A tuple containing the minimum total cost and the path taken. If no path exists, returns (-1, an empty list).</returns>
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        // Special case: starting node is the target node
        if (from == to)
        {
            return (0, new List<string> { from });
        }

        // dist stores the minimum distance from 'from' to each visited node
        var dist = new Dictionary<string, int>();
        // prev stores the predecessor of a node in the shortest path for reconstruction
        var prev = new Dictionary<string, string>();
        // priority queue to explore nodes with the smallest cumulative cost first
        var pq = new PriorityQueue<string, int>();

        dist[from] = 0;
        pq.Enqueue(from, 0);

        while (pq.Count > 0)
        {
            if (!pq.TryDequeue(out string u, out int d)) break;

            // If we have already found a shorter path to u, skip this entry
            if (d > dist.GetValueOrDefault(u, int.MaxValue)) continue;

            // Optimization: the first time 'to' is dequeued, we have found its shortest path
            if (u == to) break;

            // Explore neighbors of current node u
            if (edges.TryGetValue(u, out var neighbors))
            {
                foreach (var edge in neighbors)
                {
                    string v = edge.Key;
                    int weight = edge.Value;
                    int newDist = d + weight;

                    // If a shorter path to neighbor v is found, update dist and pq
                    if (!dist.TryGetValue(v, out int currentVDist) || newDist < currentVDist)
                    {
                        dist[v] = newDist;
                        prev[v] = u;
                        pq.Enqueue(v, newDist);
                    }
                }
            }
        }

        // If 'to' was never reached, return the failure state
        if (!dist.TryGetValue(to, out int totalCost))
        {
            return (-1, new List<string>());
        }

        // Reconstruct the path by backtracking from 'to' to 'from' using the 'prev' dictionary
        var path = new List<string>();
        string current = to;
        while (true)
        {
            path.Add(current);
            if (current == from) break;

            if (!prev.TryGetValue(current, out current))
            {
                // This case should technically be unreachable if 'to' was found in 'dist'
                return (-1, new List<string>());
            }
        }

        path.Reverse();
        return (totalCost, path);
    }
}

using System;
using System.Collections.Generic;

public static class Routes
{
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        if (from == to)
        {
            return (0, new List<string> { from });
        }

        // distances[node] stores the minimum cost found so far to reach 'node' from 'from'
        var distances = new Dictionary<string, int>();
        // previous[node] stores the predecessor of 'node' in the shortest path for reconstruction
        var previous = new Dictionary<string, string>();
        // PriorityQueue stores (Node, Cost) and prioritizes by lower cost
        var pq = new PriorityQueue<string, int>();

        distances[from] = 0;
        pq.Enqueue(from, 0);

        while (pq.Count > 0)
        {
            if (!pq.TryDequeue(out string u, out int currentDist)) break;

            // If we reached the destination, Dijkstra guarantees this is the shortest path
            if (u == to) break;

            // Standard Dijkstra check: if we found a better path to u already, skip processing its neighbors
            if (currentDist > distances.GetValueOrDefault(u, int.MaxValue)) continue;

            // Only iterate over neighbors if the node exists as a source in the edges dictionary
            if (edges.TryGetValue(u, out var neighbors))
            {
                foreach (var edge in neighbors)
                {
                    string v = edge.Key;
                    int weight = edge.Value;
                    int distanceThroughU = currentDist + weight;

                    // If this path to v is cheaper than any previously recorded path
                    if (!distances.ContainsKey(v) || distanceThroughU < distances[v])
                    {
                        distances[v] = distanceThroughU;
                        previous[v] = u;
                        pq.Enqueue(v, distanceThroughU);
                    }
                }
            }
        }

        // If the destination was never reached
        if (!distances.ContainsKey(to))
        {
            return (-1, new List<string>());
        }

        // Reconstruct path from 'to' back to 'from'
        var path = new List<string>();
        string curr = to;
        while (curr != null)
        {
            path.Add(curr);
            if (!previous.TryGetValue(curr, out curr))
            {
                break;
            }
        }
        path.Reverse();

        return (distances[to], path);
    }
}

using System;
using System.Collections.Generic;

public static class Routes
{
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        if (from == to)
        {
            return (0, new List<string> { from });
        }

        var distances = new Dictionary<string, int>();
        var previous = new Dictionary<string, string>();
        var priorityQueue = new SortedSet<(int distance, string node)>(Comparer<(int distance, string node)>.Create((a, b) =>
        {
            int res = a.distance.CompareTo(b.distance);
            if (res == 0) return string.Compare(a.node, b.node, StringComparison.Ordinal);
            return res;
        }));

        distances[from] = 0;
        priorityQueue.Add((0, from));

        while (priorityQueue.Count > 0)
        {
            var current = priorityQueue.Min;
            priorityQueue.Remove(current);

            int distU = current.distance;
            string u = current.node;

            if (u == to) break;

            if (!edges.ContainsKey(u)) continue;

            foreach (var edge in edges[u])
            {
                string v = edge.Key;
                int weight = edge.Value;
                int newDist = distU + weight;

                if (!distances.TryGetValue(v, out int distV) || newDist < distV)
                {
                    priorityQueue.Remove((distV, v)); // Remove old distance if exists
                    distances[v] = newDist;
                    previous[v] = u;
                    priorityQueue.Add((newDist, v));
                }
            }
        }

        if (!distances.ContainsKey(to))
        {
            return (-1, new List<string>());
        }

        List<string> path = new List<string>();
        for (string curr = to; curr != null; curr = previous.GetValueOrDefault(curr))
        {
            path.Add(curr);
        }
        path.Reverse();

        return (distances[to], path);
    }
}

using System;
using System.Collections.Generic;

public static class Routes
{
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        if (string.IsNullOrEmpty(from) || string.IsNullOrEmpty(to))
            return (-1, new List<string>());

        if (from == to)
            return (0, new List<string> { from });

        var dist = new Dictionary<string, int>();
        var predecessor = new Dictionary<string, string?>();
        int maxDistance = int.MaxValue;

        foreach (var kvp in edges)
        {
            if (!dist.ContainsKey(kvp.Key))
                dist[kvp.Key] = 0;

            foreach (var destKvp in kvp.Value)
            {
                if (!dist.ContainsKey(destKvp.Key))
                    dist[destKvp.Key] = 0;
            }
        }

        foreach (var node in dist.Keys)
        {
            dist[node] = maxDistance;
            predecessor[node] = null;
        }

        dist[from] = 0;

        var heap = new PriorityQueue<string, int>();
        heap.Enqueue(from, 0);

        while (heap.Count > 0)
        {
            string current = heap.Dequeue();

            if (!edges.TryGetValue(current, out Dictionary<string, int> neighbors))
                continue;

            foreach (var edge in neighbors)
            {
                int newDistance = dist[current] + edge.Value;

                if (newDistance < dist[edge.Key])
                {
                    dist[edge.Key] = newDistance;
                    predecessor[edge.Key] = current;
                    heap.Enqueue(edge.Key, newDistance);
                }
            }
        }

        if (!dist.ContainsKey(to) || dist[to] == maxDistance)
            return (-1, new List<string>());

        var path = new List<string>();
        string currentPathNode = to;
        while (currentPathNode != null)
        {
            path.Add(currentPathNode);
            if (predecessor[currentPathNode] == from && !from.Equals(predecessor[currentPathNode]))
                break;
            currentPathNode = predecessor[currentPathNode];
        }

        path.Reverse();

        return (dist[to], path);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Routes
{
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        if (from == to) return (0, new List<string> { from });

        var dist = new Dictionary<string, int>();
        var prev = new Dictionary<string, string>();
        var unvisited = new HashSet<string>(edges.Keys.Concat(edges.Values.SelectMany(v => v.Keys)));

        foreach (var node in unvisited)
            dist[node] = int.MaxValue;

        dist[from] = 0;

        while (unvisited.Count > 0)
        {
            var u = unvisited.OrderBy(n => dist[n]).FirstOrDefault();
            if (u == null || dist[u] == int.MaxValue) break;

            unvisited.Remove(u);
            if (u == to) break;

            edges.TryGetValue(u, out var neighbors);
            if (neighbors == null) continue;

            foreach (var kvp in neighbors)
            {
                var v = kvp.Key;
                var weight = kvp.Value;
                if (!unvisited.Contains(v)) continue;

                int alt = dist[u] + weight;
                if (alt < dist[v])
                {
                    dist[v] = alt;
                    prev[v] = u;
                }
            }
        }

        if (!dist.ContainsKey(to) || dist[to] == int.MaxValue)
            return (-1, new List<string>());

        var path = new List<string>();
        var curr = to;
        while (curr != null)
        {
            path.Add(curr);
            prev.TryGetValue(curr, out var p);
            curr = p;
        }
        path.Reverse();
        return (dist[to], path);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Routes
{
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to)
    {
        if (from == to)
            return (0, new List<string> { from });

        // Dijkstra's algorithm
        var dist = new Dictionary<string, int>();
        var prev = new Dictionary<string, string>();

        // Initialize distances
        foreach (var kvp in edges)
        {
            if (!dist.ContainsKey(kvp.Key))
                dist[kvp.Key] = int.MaxValue;
            foreach (var neighborKvp in kvp.Value)
            {
                if (!dist.ContainsKey(neighborKvp.Key))
                    dist[neighborKvp.Key] = int.MaxValue;
            }
        }

        // Add 'from' to dist if not present
        if (!dist.ContainsKey(from))
            dist[from] = int.MaxValue;

        // Add 'to' to dist if not present
        if (!dist.ContainsKey(to))
            dist[to] = int.MaxValue;

        dist[from] = 0;

        // Priority queue: (cost, node)
        var pq = new PriorityQueue<(int cost, string node), int>();
        pq.Enqueue((0, from), 0);

        var visited = new HashSet<string>();

        while (pq.Count > 0)
        {
            var current = pq.Dequeue();
            int currCost = current.cost;
            string currNode = current.node;

            if (visited.Contains(currNode))
                continue;
            visited.Add(currNode);

            if (currNode == to)
                break;

            // Get neighbors of currNode
            if (!edges.ContainsKey(currNode))
                continue;

            var neighborEdges = edges[currNode];
            foreach (var kvp in neighborEdges)
            {
                string nextNode = kvp.Key;
                int edgeCost = kvp.Value;

                if (visited.Contains(nextNode))
                    continue;

                int newDist = currCost + edgeCost;
                if (newDist < dist[nextNode])
                {
                    dist[nextNode] = newDist;
                    prev[nextNode] = currNode;
                    pq.Enqueue((newDist, nextNode), newDist);
                }
            }
        }

        if (!dist.ContainsKey(to) || dist[to] == int.MaxValue)
            return (-1, new List<string>());

        // Reconstruct path
        var path = new List<string>();
        string node = to;
        while (true)
        {
            path.Add(node);
            if (!prev.ContainsKey(node))
                break;
            node = prev[node];
        }
        path.Reverse();

        return (dist[to], path);
    }
}

using System;
using System.Collections.Generic;

public static class Routes {
    public static (int Cost, List<string> Path) Cheapest(Dictionary<string, Dictionary<string, int>> edges, string from, string to) {
        if (from == to) return (0, new List<string> { from });

        var dist = new Dictionary<string, int>();
        var parent = new Dictionary<string, string>();
        var pq = new PriorityQueue<string, int>();

        dist[from] = 0;
        pq.Enqueue(from, 0);

        while (pq.Count > 0) {
            if (!pq.TryDequeue(out var u, out var d)) continue;

            if (d > dist.GetValueOrDefault(u, int.MaxValue)) continue;
            if (u == to) break;

            if (edges.TryGetValue(u, out var neighbors)) {
                foreach (var kvp in neighbors) {
                    string v = kvp.Key;
                    int w = kvp.Value;
                    int newDist = d + w;

                    if (!dist.ContainsKey(v) || newDist < dist[v]) {
                        dist[v] = newDist;
                        parent[v] = u;
                        pq.Enqueue(v, newDist);
                    }
                }
            }
        }

        if (!dist.TryGetValue(to, out int cost)) {
            return (-1, new List<string>());
        }

        var path = new List<string>();
        string curr = to;
        while (curr != from) {
            path.Add(curr);
            curr = parent[curr];
        }
        path.Add(from);
        path.Reverse();

        return (cost, path);
    }
}

