public class RingBuffer<T>
{
    private readonly T[] _buffer;
    private readonly int _capacity;
    private int _head; // Index of the oldest element
    private int _count; // Number of elements currently in the buffer

    public RingBuffer(int capacity)
    {
        if (capacity < 1)
        {
            throw new ArgumentOutOfRangeException(nameof(capacity), "Capacity must be at least 1.");
        }

        _capacity = capacity;
        _buffer = new T[capacity];
        _head = 0;
        _count = 0;
    }

    public int Count => _count;

    public void Add(T item)
    {
        if (_count < _capacity)
        {
            // Buffer is not full, calculate the next available slot based on head and count
            int index = (_head + _count) % _capacity;
            _buffer[index] = item;
            _count++;
        }
        else
        {
            // Buffer is full, overwrite the oldest element (which is at _head)
            _buffer[_head] = item;
            // The new head becomes the next element in the circular sequence
            _head = (_head + 1) % _capacity;
            // Count remains equal to capacity
        }
    }

    public T this[int i]
    {
        get
        {
            if (i < 0 || i >= _count)
            {
                throw new ArgumentOutOfRangeException(nameof(i), "Index is out of the range of elements currently in the buffer.");
            }

            // The index relative to the current oldest element
            int actualIndex = (_head + i) % _capacity;
            return _buffer[actualIndex];
        }
    }

    public T[] ToArray()
    {
        T[] result = new T[_count];
        for (int i = 0; i < _count; i++)
        {
            // Using the indexer to ensure logic is consistent and oldest-first order
            result[i] = this[i];
        }
        return result;
    }
}

