def parse_duration(text: str) -> int:
    s = text.strip()
    if not s:
        raise ValueError("Empty string")

    if not all(c.isdigit() or c in 'hms' for c in s):
        raise ValueError("Invalid characters found")

    matches = list(re.finditer(r'\d+[hms]', s))
    if not matches:
        raise ValueError("No valid duration components found")

    if ''.join(m.group() for m in matches) != s:
        raise ValueError("Invalid format")

    units_order = {'h': 0, 'm': 1, 's': 2}
    last_idx = -1
    total = 0

    for match in matches:
        num_str, unit = match.group()[:-1], match.group()[-1]
        val = int(num_str)

        curr_idx = units_order[unit]
        if curr_idx <= last_idx:
            raise ValueError("Units out of order or repeated")

        if unit == 'h':
            total += val * 3600
        elif unit == 'm':
            total += val * 60
        else:
            total += val

        last_idx = curr_idx

    return total

