    try:
        core_a = tuple(int(x) for x in core_a_str.split('.'))
        core_b = tuple(int(x) for x in core_b_str.split('.'))
    except ValueError:
        # Fallback or error handling if input doesn't match expected pattern
        return 0

    if core_a < core_b:
        return -1
    elif core_a > core_b:
        return 1

    # If cores are equal, handle pre-release logic.
    # A version with a pre-release is lower than the same version without one.
    if pre_a_str is None and pre_b_str is not None:
        return 1
    if pre_a_str is not None and pre_b_str is None:
        return -1
    if pre_a_str is None and pre_b_str is None:
