    list_b = parse_pre(pre_b_str)

    # Compare identifiers left to right
    for i in range(min(len(list_a), len(list_b))):
        id_a = list_a[i]
        id_b = list_b[i]

        # Check types for numeric vs alphanumeric rules
        if type(id_a) is not type(id_b):
            # Numeric identifiers are lower than alphanumeric ones.
            return -1 if isinstance(id_a, int) else 1
        else:
            # Both have the same type (both int or both str)
            if id_a < id_b:
