        if pre_release_part is None:
            # A version without a pre-release is "greater" than one with (e.g., 1.2.3 > 1.2.3-alpha)
            # We represent this by using a flag that forces core comparison to win, 
            # but since we return early in logic, we treat the existence of pre-release as "lesser".
            return (core_tuple, True, [])

        # Parse pre-release identifiers
        pre_release_identifiers = []
        for identifier in pre_release_part.split('.'):
            if identifier.isdigit():
                pre_release_identifiers.append((0, int(identifier)))
            else:
                pre_release_identifiers.append((1, identifier))

        return (core_tuple, False, pre_release_identifiers)

