        # If one has no pre-release and other does, the one without is GREATER.
        # In our parse logic: True = No pre-release, False = Has pre-release.
        # However, it's easier to handle this in the main loop.
        for id_a, id_b in zip(pre_a, pre_b):
            type_a, val_a = id_a
            type_b, val_b = id_b

            if type_a != type_b:
                # Numeric (0) < Alphanumeric (1)
                return -1 if type_a < type_b else 1
            else:
                if val_a == val_b:
                    continue
                return -1 if val_a < val_b else 1

        # All identifiers equal up to the length of the shorter list
        if len(pre_a) == len(pre_b):
            return 0
        return -1 if len(pre_a) < len(pre_b) else 1

