def compare_versions(a: str, b: str) -> int:
    """
    Compare two semantic versions according to SemVer 2.0.0 rules.

    Returns -1 if a < b, 0 if equal, 1 if a > b.
    """

    def parse_version(v: str):
        """Parse a version string into (major, minor, patch, pre_release_identifiers)"""
        # Split off the pre-release part after hyphen
        if '-' in v:
            main_part, prerelease = v.split('-', 1)
        else:
            main_part = v
            prerelease = None

        # Parse major.minor.patch
        parts = main_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease)

    def compare_prerelease(pre_a, pre_b):
        """Compare two pre-release identifier lists according to SemVer rules."""
        # If neither has a pre-release, they are equal in this component
        if pre_a is None and pre_b is None:
            return 0
        # A version with pre-release is lower than one without
        if pre_a is not None and pre_b is None:
            return -1
        if pre_a is None and pre_b is not None:
            return 1

        # Split pre-release identifiers by dot
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        for i in range(max(len(ids_a), len(ids_b))):
            if i >= len(ids_a):
                # a ran out, b has more => a is shorter and equal so far => a < b
                return -1
            if i >= len(ids_b):
                # b ran out, a has more => b is shorter and equal so far => a > b
                return 1

            id_a = ids_a[i]
            id_b = ids_b[i]

            # Check if both are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            if is_numeric_a and is_numeric_b:
                # Compare as numbers
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
                else:
                    continue
            elif is_numeric_a and not is_numeric_b:
                # Numeric identifiers have lower precedence than alphanumeric
                return -1
            elif not is_numeric_a and is_numeric_b:
                # Alphanumeric has higher precedence than numeric
                return 1
            else:
                # Both are alphanumeric, compare by ASCII string comparison
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
                else:
                    continue

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch numerically
    for comp_a, comp_b in [(major_a, major_b), (minor_a, minor_b), (patch_a, patch_b)]:
        if comp_a < comp_b:
            return -1
        elif comp_a > comp_b:
            return 1

    # If major.minor.patch are equal, compare pre-release
    return compare_prerelease(pre_a, pre_b)

