        if prerelease is not None:
            identifiers = []
            for ident in prerelease.split('.'):
                if ident.isdigit():
                    # Numeric identifier: compare numerically, and it's lower than alphanumeric
                    identifiers.append((0, int(ident), ''))
                else:
                    identifiers.append((1, 0, ident))
        else:
            identifiers = None

        return (major, minor, patch, identifiers)

    a_parsed = parse(a)
    b_parsed = parse(b)

    # Compare major
    if a_parsed[0] != b_parsed[0]:
        return -1 if a_parsed[0] < b_parsed[0] else 1
    # Compare minor
    if a_parsed[1] != b_parsed[1]:
        return -1 if a_parsed[1] < b_parsed[1] else 1
    # Compare patch
    if a_parsed[2] != b_parsed[2]:
        return -1 if a_parsed[2] < b_parsed[2] else 1

    # Both have same major.minor.patch; compare pre-release
    a_pr = a_parsed[3]
    b_pr = b_parsed[3]

    if a_pr is None and b_pr is None:
        return 0
    elif a_pr is not None and b_pr is None:
        # Version with pre-release is lower than without
        return -1
    elif a_pr is None and b_pr is not None:
        return 1

    # Both have pre-releases; compare identifiers left to right
    for i in range(max(len(a_pr), len(b_pr))):
        if i < len(a_pr) and i < len(b_pr):
            ident_a = a_pr[i]
            ident_b = b_pr[i]

            # First element: 0 for numeric, 1 for alphanumeric. Numeric is lower.
            if ident_a[0] != ident_b[0]:
                return -1 if ident_a[0] < ident_b[0] else 1

            if ident_a[0] == 0 and ident_b[0] == 0:
                # Both numeric, compare numerically
                if ident_a[1] != ident_b[1]:
                    return -1 if ident_a[1] < ident_b[1] else 1
            elif ident_a[0] == 1 and ident_b[0] == 1:
                # Both alphanumeric, compare by ASCII order
                if ident_a[2] != ident_b[2]:
                    return -1 if ident_a[2] < ident_b[2] else 1
            # If one is numeric and the other alphanumeric, handled above by type mismatch
        elif i < len(a_pr):
            # a has more identifiers, so a > b (shorter list is lower)
            return 1
        elif i < len(b_pr):
            return -1

    return 0

def compare_versions(a: str, b: str) -> int:
    def parse(v):
        core, _, pre = v.partition("-")
        nums = tuple(int(x) for x in core.split("."))
        ids = pre.split(".") if pre else []
        return (nums, ids)

    def cmp_ints(t1, t2):
        for i, j in zip(t1, t2):
            if i != j:
                return -1 if i < j else 1
        return len(t1) - len(t2)

    na, ia = parse(a)
    nb, ib = parse(b)
    c = cmp_ints(na[:3], nb[:3])
    if c != 0:
        return c
    la, lb = (not not ia), (not not ib)
    if la != lb:
        return -1 if la else 1
    if not la:
        return 0
    for x, y in zip(ia, ib):
        nx, ny = x.isdigit(), y.isdigit()
        if nx and ny:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif nx:
            return -1
        elif ny:
            return 1
        elif x != y:
            return -1 if x < y else 1
    return len(ia) - len(ib)

