    """
    Adds qty of item into slots. First tops up existing stacks of the same item, 
    then fills empty slots in order. Returns the quantity that did not fit.
    """
    # Step 1: Top up existing stacks of the same item
    for i in range(len(slots)):
        if qty <= 0:
            break
        if slots[i] is not None and slots[i][0] == item:
            current_count = slots[i][1]
            can_add = max_stack - current_count
            if can_add > 0:
                to_add = min(qty, can_add)
                slots[i][1] += to_add
                qty -= to_add

    # Step 2: Fill empty slots in order
    for i in range(len(slots)):
        if qty <= 0:
            break
        if slots[i] is None:
            to_add = min(qty, max_stack)
            slots[i] = [item, to_add]
            qty -= to_add

    return qty

