export function applyHit(
  state: { hp: number; shield: number },
  damage: number,
  pierce: boolean
): { hp: number; shield: number; dead: boolean } {
  const effectiveDamage = Math.max(0, damage);

  let newShield: number = state.shield;
  let newHp: number = state.hp;

  if (pierce) {
    // If pierce is true, the shield is untouched and all damage goes to hp
    newHp = Math.max(0, state.hp - effectiveDamage);
  } else {
    // Otherwise, shield absorbs damage first
    const absorbedByShield = Math.min(state.shield, effectiveDamage);
    newShield = state.shield - absorbedByShield;

    const remainingDamage = effectiveDamage - absorbedByShield;
    newHp = Math.max(0, state.hp - remainingDamage);
  }

  return {
    hp: newHp,
    shield: newShield,
    dead: newHp === 0,
  };
}

