export function deepEqual(a: unknown, b: unknown): boolean {
    if (a === b) return true;
    if (Number.isNaN(a as number) && Number.isNaN(b as number)) return true;
    if (typeof a !== 'object' || typeof b !== 'object') return false;
    if (a === null || b === null) return false;
    const isArrA = Array.isArray(a), isArrB = Array.isArray(b);
    if (isArrA !== isArrB) return false;
    if (isArrA) {
        const arrA = a as unknown[], arrB = b as unknown[];
        if (arrA.length !== arrB.length) return false;
        return arrA.every((v, i) => deepEqual(v, arrB[i]));
    }
    const objA = Object.keys(a as object), objB = Object.keys(b as object);
    if (objA.length !== objB.length) return false;
    for (const k of objA) {
        if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
        if (!deepEqual((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k])) return false;
    }
    return true;
