  const dc = [0, 0, -1, 1]; // col directions: up, down, left, right

  while (head < queue.length) {
    const [r, c, dist] = queue[head++];

    // If we've reached the target destination
    if (r === endR && c === endC) return dist;

    for (let i = 0; i < 4; i++) {
      const nr = r + dr[i];
