 * @returns The minimum number of moves, or -1 if no path exists.
 */
export function shortestPath(grid: string[]): number {
  const rows = grid.length;
  if (rows === 0) return -1;
  const cols = grid[0].length;

  let startPos: [number, number] | null = null;
  let endPos: [number, number] | null = null;

  // Find Start and End coordinates
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 'S') {
        startPos = [r, c];
      } else if (grid[r][c] === 'E') {
        endPos = [r, c];
      }
    }
  }

  if (!startPos || !endPos) return -1;

  // BFS setup: queue stores [row, col, distance]
  const queue: [number, number, number][] = [[startPos[0], startPos[1], 0]];
  const visited = new Set<string>();
  visited.add(`${startPos[0]},${startPos[1]}`);

  const directions = [
    [0, 1],  // Right
    [0, -1], // Left
    [1, 0],  // Down
    [-1, 0], // Up
  ];

  let head = 0;
  while (head < queue.length) {
    const [r, c, dist] = queue[head++];

    if (r === endPos![0] && c === endPos![1]) {
      return dist;
    }

    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;

      if (
        nr >= 0 &&
        nr < rows &&
        nc >= 0 &&
        nc < cols &&
        grid[nr][nc] !== '#' &&
        !visited.has(`${nr},${nc}`)
      ) {
        visited.add(`${nr},${nc}`);
        queue.push([nr, nc, dist + 1]);
      }
    }
  }

  return -1;
}

/**
