export function shortestPath(grid: string[]): number {
  if (!grid || grid.length === 0) return -1;

  const rows = grid.length;
  const cols = grid[0].length;
  let startX = -1, startY = -1;

  // Locate the starting position 'S'
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 'S') {
        startX = r;
        startY = c;
        break;
      }
    }
    if (startX !== -1) break;
  }

  // If start is not found, it's unreachable
  if (startX === -1) return -1;

  const directions = [
    [0, 1],  // Right
    [0, -1], // Left
    [1, 0],  // Down
    [-1, 0], // Up
  ];

  // Queue stores: [row, col, distance]
  const queue: [number, number, number][] = [[startX, startY, 0]];
  const visited = new Uint8Array(rows * cols);
  visited[startX * cols + startY] = 1;

  let head = 0; // Using a pointer for the queue to avoid O(n) shift() operations
  while (head < queue.length) {
    const [r, c, dist] = queue[head++];

    // Check if we reached the destination 'E'
    if (grid[r][c] === 'E') {
      return dist;
    }

    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;

      // Bounds check and collision/visited check
      if (
        nr >= 0 && 
        nr < rows && 
        nc >= 0 && 
        nc < cols && 
        grid[nr][nc] !== '#' && 
        !visited[nr * cols + nc]
      ) {
        visited[nr * cols + nc] = 1;
        queue.push([nr, nc, dist + 1]);
      }
    }
  }

  return -1; // Destination not reachable
}

