export function matches(pattern: string, text: string): boolean {
  const m = pattern.length;
  const n = text.length;

  // dp[i][j] will be true if the first i characters of the pattern 
  // match the first j characters of the text.
  const dp: boolean[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(false));

  // Base case: empty pattern matches empty text.
  dp[0][0] = true;

  // Handle cases where the pattern starts with '*' which can match an empty string.
  for (let i = 1; i <= m; i++) {
    if (pattern[i - 1] === '*') {
      dp[i][0] = dp[i - 1][0];
    } else {
      // If we encounter a non-* character, no subsequent prefix can match an empty string.
      break;
    }
  }

  for (let i = 1; i <= m; i++) {
    const pChar = pattern[i - 1];
    for (let j = 1; j <= n; j++) {
      if (pChar === '?' || pChar === text[j - 1]) {
        // If characters match or pattern has '?', result depends on the previous state.
        dp[i][j] = dp[i - 1][j - 1];
      } else if (pChar === '*') {
        // If pattern character is '*', it can:
        // 1. Match zero characters: dp[i-1][j]
        // 2. Match one or more characters: dp[i][j-1]
        dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
      } else {
        // Characters don't match.
        dp[i][j] = false;
      }
    }
  }

  return dp[m][n];
}

/**
 * Determines if a given text matches a pattern where:
 * '?' matches exactly one character.
 * '*' matches any sequence of characters (including none).
 * Other characters match themselves literally.
 * The entire text must be matched by the pattern.
 */
export function matches(pattern: string, text: string): boolean {
  const n = pattern.length;
  const m = text.length;

  // dp[i][j] will be true if pattern[0...i-1] matches text[0...j-1]
  const dp: boolean[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(false));

  // Base case: empty pattern matches empty text
  dp[0][0] = true;

  // Handle patterns starting with '*' which can match an empty string
  for (let i = 1; i <= n; i++) {
    if (pattern[i - 1] === '*') {
      dp[i][0] = dp[i - 1][0];
    } else {
      break; // Once we hit a non-'*' char, no more empty text matches possible for this pattern prefix
    }
  }

  for (let i = 1; i <= n; i++) {
    const pChar = pattern[i - 1];

    for (let j = 1; j <= m; j++) {
      if (pChar === '*') {
        // '*' matches:
        // 1. Zero characters in text (dp[i-1][j])
        // 2. One or more characters in text (dp[i][j-1])
        dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
      } else if (pChar === '?' || pChar === text[j - 1]) {
        // '?' or exact character match depends on the previous diagonal state
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        // Characters don't match
        dp[i][j] = false;
      }
    }
  }

  return dp[n][m];
}

