export function matches(pattern: string, text: string): boolean {
  let p = 0; // Pattern pointer
  let t = 0; // Text pointer
  let starIdx = -1; // Index of the last encountered '*' in the pattern
  let matchIdx = 0; // The index in the text that was matched by the last '*'

  while (t < text.length) {
    // Case 1: Characters match or pattern has '?'
    if (p < pattern.length && (pattern[p] === '?' || pattern[p] === text[t])) {
      p++;
      t++;
    } 
    // Case 2: Pattern has '*', mark the position and try matching zero characters first
    else if (p < pattern.length && pattern[p] === '*') {
      starIdx = p;
      matchIdx = t;
      p++;
    } 
    // Case 3: Current match fails, but we encountered a '*' previously.
    // Backtrack to the last '*' and try matching one more character from text.
    else if (starIdx !== -1) {
      p = starIdx + 1;
      matchIdx++;
      t = matchIdx;
    } 
    // Case 4: No match and no preceding '*' to backtrack to
    else {
      return false;
    }
  }

  // The text has been fully traversed. Ensure the remaining pattern consists only of '*'
  while (p < pattern.length && pattern[p] === '*') {
    p++;
  }

  return p === pattern.length;
}

export function matches(pattern: string, text: string): boolean {
