    let tIdx = 0;
    let starIdx = -1;
    let matchIdx = 0;

    while (tIdx < text.length) {
        // If current characters match or pattern has '?'
        if (pIdx < pattern.length && (pattern[pIdx] === '?' || pattern[pIdx] === text[tIdx])) {
            pIdx++;
            tIdx++;
        } 
        // If pattern has '*', record position and try matching 0 characters first
        else if (pIdx < pattern.length && pattern[pIdx] === '*') {
            starIdx = pIdx;
            matchIdx = tIdx;
            pIdx++;
        } 
        // If mismatch occurs, backtrack to the last '*' encountered
        else if (starIdx !== -1) {
            pIdx = starIdx + 1;
            matchIdx++;
            tIdx = matchIdx;
        } 
        // No match possible
        else {
            return false;
        }
    }

    // Check for remaining characters in pattern (only '*' are allowed)
    while (pIdx < pattern.length && pattern[pIdx] === '*') {
        pIdx++;
    }

    return pIdx === pattern.length;
}

export function matches(pattern: string, text: string): boolean {
    const m = pattern.length;
    const n = text.length;

    // dp[i][j] means pattern[0..i-1] can match text[0..j-1]
    const dp: boolean[][] = Array(m + 1).fill(null)
        .map(() => Array(n + 1).fill(false));

    // Empty pattern matches empty text
    dp[0][0] = true;

    // Initialize for empty text (only possible with * patterns)
    for (let i = 1; i <= m; i++) {
        if (pattern[i - 1] === '*') {
            const prevIndex = pattern[i - 2];
            dp[i][0] = dp[i - 2][0] || (prevIndex !== '?' && prevIndex !== '*');
        } else {
            dp[i][0] = false;
        }
    }

    // Fill the DP table
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const pChar = pattern[i - 1];
            const tChar = text[j - 1];

            if (pChar === '*') {
                // * can match zero characters: dp[i-1][j]
                // or one or more characters: dp[i][j-1] AND prev char matches current text char
                dp[i][j] = dp[i - 1][j] || 
                    (dp[i][j - 1] && (pattern[i - 2] === '?' || pattern[i - 2] === tChar));
            } else if (pChar === '?') {
                // ? matches any single character
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                // Regular character must match exactly one character
                dp[i][j] = dp[i - 1][j - 1] && (pChar === tChar);
            }
        }
    }

    return dp[m][n];
}

export function matches(pattern: string, text: string): boolean {
  const pArray = Array.from(pattern);
  const tArray = Array.from(text);
  let pIndex = 0;
  let tIndex = 0;

  while (tIndex < tArray.length) {
    if (pIndex >= pArray.length) return false;

    if (pArray[pIndex] === '?') {
      tIndex++;
    } else if (pArray[pIndex] === '*') {
      // Try matching '*' with zero characters first, then incrementally more
      let starP = pIndex + 1;
      let starT = tIndex;

      while (starT < tArray.length && (starP >= pArray.length || pArray[starP] !== '*')) {
        if (pArray[starP] === '?' || pArray[starP] === tArray[starT]) {
          starT++;
        } else {
          return false; // Mismatch and can't use more of the '*' to fix it
        }
        starP++;
      }

      if (pIndex < pArray.length && pArray[pIndex] !== '*') {
        pIndex = starP;
        tIndex = starT;
      }
    } else {
      // Exact match required or '?' handled above, so just check exact char
      if (pArray[pIndex] !== tArray[tIndex]) return false;
      tIndex++;
      pIndex++;
    }
  }

  while (pIndex < pArray.length && pArray[pIndex] === '*') {
    pIndex++;
  }

  // Pattern must be fully consumed for a full match, except trailing '*'s which are handled above.
  // However, if there are leftover characters in pattern that aren't '*' or '?' (impossible here since loop finishes), 
  // we check if all remaining chars are '*'. If so, they match empty text, which is allowed.
  return pIndex === pArray.length || (pArray.slice(pIndex).every(c => c === '*'));
}

export const matches = (pattern: string, text: string): boolean => {
  if (!pattern) return !text;
  let i = 0;
  let j = 0;
  while (i < pattern.length && j <= text.length) {
    const pChar = pattern[i++];
    if (pChar === '?') {
      if (j >= text.length) return false;
      j++;
    } else if (pChar === '*') {
      let k = j;
      while (k < text.length) {
        if (matches(pattern.slice(i), text.slice(k))) return true;
        k++;
      }
      break;
    } else if (pattern[i - 1] !== pattern.charAt(i - 2)) {
      if (pChar === text[j]) j++;
      else return false;
    } else if ((j >= text.length) || (text[j - 1] !== pChar)) return false;
  }
  return i > pattern.length && j === text.length + (pattern.lastIndexOf('*') < pattern.length ? 0 : 0);
};

export function matches(pattern: string, text: string): boolean {
    const m = pattern.length;
    const n = text.length;

    // dp[i][j] means whether pattern[0..i-1] matches text[0..j-1]
    const dp: boolean[][] = new Array(m + 1).fill(null).map(() => new Array(n + 1).fill(false));

    // Empty pattern matches empty text
    dp[0][0] = true;

    // Handle patterns with leading '*' which can match empty sequence
    for (let i = 1; i <= m; i++) {
        if (pattern[i - 1] === '*') {
            dp[i][0] = dp[i - 1][0];
        } else {
            break; // Once we hit a non-'*', further '*' can't help match empty text since earlier chars must also match
        }
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (pattern[i - 1] === '*') {
                // '*' matches zero characters: dp[i-1][j]
                // '*' matches one or more characters: dp[i][j-1]
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pattern[i - 1] === '?') {
                // '?' matches exactly one character
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                // Regular character must match exactly
                dp[i][j] = dp[i - 1][j - 1] && pattern[i - 1] === text[j - 1];
            }
        }
    }

    return dp[m][n];
}

