export function matches(pattern: string, text: string): boolean {
    const pLen = pattern.length;
    const tLen = text.length;

    // dp[i][j] means whether pattern[0..i-1] matches text[0..j-1]
    const dp: boolean[][] = Array.from({ length: pLen + 1 }, () => 
        new Array(tLen + 1).fill(false)
    );

    // Empty pattern matches empty text
    dp[0][0] = true;

    // Handle patterns like *, **, *** that can match empty string
    for (let i = 1; i <= pLen; i++) {
        if (pattern[i - 1] === '*') {
            dp[i][0] = dp[i - 1][0];
        } else {
            break;
        }
    }

    for (let i = 1; i <= pLen; i++) {
        const pc = pattern[i - 1];
        for (let j = 1; j <= tLen; j++) {
            const tc = text[j - 1];

            if (pc === '*') {
                // '*' matches zero characters or one/more characters
                // dp[i-1][j]: '*' matches zero chars from current position in text
                // dp[i][j-1]: '*' matches at least one character, consuming the last char of text
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc === '?' || pc === tc) {
                // '?' or exact match: depends on previous state without these chars
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                // Mismatch
                dp[i][j] = false;
            }
        }
    }

    return dp[pLen][tLen];
}

